package cli

import (
	"fmt"
	"strings"

	"github.com/mvanhorn/printing-press-library/library/commerce/flipkart/internal/store"

	"github.com/spf13/cobra"
)

func newCompareCmd(flags *rootFlags) *cobra.Command {
	cmd := &cobra.Command{
		Use:   "compare <url1> <url2> [url3...]",
		Short: "Line up 2 or more Flipkart products side by side: price, rating, brand, discount.",
		Long:  "Fetches each given product URL and renders a side-by-side comparison. Discount percentage is only shown when a prior 'product offers' run has resolved it for that product locally — otherwise it's left blank rather than guessed.",
		Example: strings.Trim(`
  flipkart-pp-cli compare "https://www.flipkart.com/oppo-a3x-8-gb-ram-128-gb-storage-lake-green/p/itmc050065f36601?pid=MOBH4ZCFEQZFQBFB" "https://www.flipkart.com/samsung-galaxy-m06-5g-mint-green-128-gb/p/itmc0501a8c1f5e5?pid=MOBH8QSVDVBRZFNJ"
`, "\n"),
		Annotations: map[string]string{"mcp:read-only": "true"},
		RunE: func(cmd *cobra.Command, args []string) error {
			if len(args) == 0 {
				return cmd.Help()
			}
			if len(args) < 2 {
				return usageErr(fmt.Errorf("compare requires at least 2 product URLs, got %d\nUsage: %s <url1> <url2> [url3...]", len(args), cmd.CommandPath()))
			}

			if dryRunOK(flags) {
				fmt.Fprintln(cmd.ErrOrStderr(), "would fetch and compare:")
				for _, u := range args {
					fmt.Fprintf(cmd.ErrOrStderr(), "  %s\n", u)
				}
				fmt.Fprintln(cmd.ErrOrStderr(), "(dry run - no request sent)")
				return nil
			}

			c, err := flags.newClient()
			if err != nil {
				return err
			}

			// Best-effort local lookup of previously resolved discount data;
			// absence of a local DB or a miss per-product is not an error.
			db, dbErr := store.OpenWithContext(cmd.Context(), defaultDBPath("flipkart-pp-cli"))
			if dbErr == nil {
				defer db.Close()
				_ = db.EnsureFlipkartSchema()
			}

			products := make([]*flipkartProduct, 0, len(args))
			for _, u := range args {
				p, err := fetchProductDetail(cmd.Context(), c.HTTPClient, u)
				if err != nil {
					return classifyFetchErr(fmt.Errorf("fetching %s: %w", u, err))
				}
				if dbErr == nil {
					if stored, err := db.GetFlipkartProduct(p.ProductID); err == nil && stored != nil {
						p.DiscountPct = stored.DiscountPct
					}
				}
				products = append(products, p)
			}

			if flags.asJSON || (!isTerminal(cmd.OutOrStdout()) && !flags.csv && !flags.quiet && !flags.plain) {
				return printJSONFiltered(cmd.OutOrStdout(), products, flags)
			}
			if wantsHumanTable(cmd.OutOrStdout(), flags) {
				rows := make([]map[string]any, len(products))
				for i, p := range products {
					rows[i] = map[string]any{
						"title":        p.Title,
						"brand":        p.Brand,
						"price":        p.Price,
						"currency":     p.Currency,
						"rating":       p.Rating,
						"discount_pct": p.DiscountPct,
					}
				}
				return printAutoTable(cmd.OutOrStdout(), rows)
			}
			return printJSONFiltered(cmd.OutOrStdout(), products, flags)
		},
	}
	return cmd
}
